import sys
input = sys.stdin.read

def solve_garland(s):
    n = len(s)
    color_positions = {}
    dead_count = {'R': 0, 'B': 0, 'Y': 0, 'G': 0}

    # Determine the positions of each color in the pattern
    for i in range(4):
        if s[i] in "RBYG":
            color_positions[s[i]] = i % 4

    # Count the dead bulbs for each color based on their positions
    for i in range(n):
        if s[i] == '!':
            pos = i % 4
            for color, color_pos in color_positions.items():
                if color_pos == pos:
                    dead_count[color] += 1

    # Print the number of dead bulbs for each color in the order R, B, Y, G
    print(dead_count['R'], dead_count['B'], dead_count['Y'], dead_count['G'])

data = input().strip()
